mapper.insert:

    SELECT SEQ_CANCEL_NO.NEXTVAL FROM DUAL

INSERT INTO CANCEL_REQUEST (
    CANCEL_NO, ORDER_ITEM_NO, MEMBER_NO, REASON, STATUS, CREATED_AT
) VALUES (
    #{cancelNo}, #{orderItemNo}, #{memberNo}, #{reason}, 'WAITING', SYSDATE
)

mapper.select:
SELECT CR.CANCEL_NO, CR.ORDER_ITEM_NO, OI.ORDER_NO, CR.MEMBER_NO, OI.BUSINESS_NO, OI.PRODUCT_NO, P.PRODUCT_NAME, OI.PRODUCT_PRICE, OI.QUANTITY, (OI.PRODUCT_PRICE * OI.QUANTITY) AS CANCEL_AMOUNT, CR.REASON, CR.STATUS, CR.CREATED_AT, CR.PROCESSED_AT, CR.REJECT_REASON FROM CANCEL_REQUEST CR JOIN ORDER_ITEM OI ON OI.ORDER_ITEM_NO = CR.ORDER_ITEM_NO JOIN PRODUCT P ON P.PRODUCT_NO = OI.PRODUCT_NO WHERE OI.BUSINESS_NO = #{businessNo}
AND CR.STATUS = #{status}
ORDER BY CASE CR.STATUS WHEN 'WAITING' THEN 1 ELSE 2 END, CR.CREATED_AT DESC, CR.CANCEL_NO DESC

mapper.update:
UPDATE CANCEL_REQUEST
   SET STATUS = 'REJECTED',
       PROCESSED_AT = SYSDATE,
       REJECT_REASON = #{rejectReason}
 WHERE CANCEL_NO = #{cancelNo}
   AND STATUS = 'WAITING'

UPDATE PRODUCT
   SET STOCK = STOCK + #{quantity}
 WHERE PRODUCT_NO = #{productNo}
